<?php

declare(strict_types=1);

namespace Domain\Sharing\Calls;

use App\Contracts\Domains\CallSender;
use Domain\Sharing\Data\ShareProposalStatusData;
use App\Support\CallKey;

/**
 * The signed calls of Sharing, generated by php artisan journal:calls; run it again instead of editing.
 */
final readonly class SharingCalls
{
    public function __construct(private CallSender $sender) {}

    public function requestShare(
        string $alias,
        string $number,
        CallKey $requestKey = new CallKey(),
    ): ShareProposalStatusData {
        return $this->sender->send(RequestShareCall::from([
            'alias' => $alias,
            'number' => $number,
            'requestKey' => $requestKey,
        ]));
    }

    public function shareStatus(
    ): ShareProposals {
        return $this->sender->send(ShareStatusCall::from([
        ]));
    }
}
